import { AuthController } from "@/modules/auth/controller";
import { loginSchema } from "@/modules/auth/schemas";
import {
  success,
  failure
} from "@/common/apiResponse";
import { cookies } from "next/headers";


const controller =
new AuthController();



export async function POST(
request:Request
){

try{


const body =
await request.json();


const data =
loginSchema.parse(body);



const result =
await controller.login(
 data.email,
 data.password
);



const cookieStore =
await cookies();



cookieStore.set(
"token",
result.token,
{
 httpOnly:true,
 secure:false,
 sameSite:"lax",
 maxAge:60 * 60 * 24 * 7,
 path:"/"
}
);



return success({
 user:result.user
});



}catch(error){

return failure(error);

}

}